{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Prasugrel, a thienopyridine prodrug sharing the same fused thienopyridine core and ester prodrug motif, has approximately 79% oral bioavailability in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Pethidine, a phenylpiperidine ester with a basic amine, has an absolute oral bioavailability of about 0.52 in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Amlodipine, a chlorophenyl dihydropyridine ester with a basic amine, has a mean systemic availability of 64% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Felodipine, a structurally related dihydropyridine ester, has a systemic availability of about 15% in healthy subjects, providing contradictory low-F evidence, but its lower similarity and distinct dihydropyridine first-pass metabolism reduce its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%). The closest thienopyridine analog prasugrel has ~79% human oral bioavailability, and other moderately similar ester/amine drugs such as amlodipine and pethidine show F values of 50-90%. The low-F felodipine evidence is less transferable and reflects dihydropyridine-specific first-pass metabolism.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the exact query molecule.",
    "The closest high-F analog prasugrel differs in acyl substituent and thiophene substitution, so first-pass hydrolysis and activation may differ.",
    "Some records do not clearly distinguish absolute bioavailability of the parent ester from that of the active metabolite."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

